<?php use App\Support\Ui; ?>
<div class="page-heading"><div><span class="eyebrow">PEOPLE</span><h1>Candidates</h1><p>Find active or inactive profiles and review interview history.</p></div><a class="button primary" href="<?= $e($url('admin/interview/new')) ?>"><?= Ui::icon('plus') ?>Book interview</a></div>
<details class="mobile-filter-sheet"><summary><?= Ui::icon('filter') ?>Filters<?php $filterCount=count(array_filter($filters));if($filterCount):?><span><?= $e($filterCount) ?></span><?php endif;?></summary><form class="filter-bar compact-filters candidate-filters card" method="get">
    <div class="field filter-search"><label for="search">Name or phone</label><input id="search" name="search" value="<?= $e($filters['search']) ?>"></div>
    <div class="field"><label for="technology_id">Candidate Tech Stack</label><select id="technology_id" name="technology_id"><option value="">All skills</option><?php foreach($technologies as $t):?><option value="<?= $e($t['id']) ?>" <?= $filters['technology_id']===(string)$t['id']?'selected':'' ?>><?= $e($t['name']) ?></option><?php endforeach;?></select></div>
    <div class="field"><label for="classification">Classification</label><select id="classification" name="classification"><option value="">All</option><option <?= $filters['classification']==='Genuine'?'selected':'' ?>>Genuine</option><option <?= $filters['classification']==='Fake'?'selected':'' ?>>Fake</option></select></div>
    <div class="field"><label for="status">Status</label><select id="status" name="status"><option value="">All</option><option value="active" <?= $filters['status']==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= $filters['status']==='inactive'?'selected':'' ?>>Inactive</option></select></div>
    <button class="button primary">Filter</button><a class="button secondary" href="<?= $e($url('admin/candidates')) ?>">Clear</a>
</form></details>
<section class="candidate-directory"><?php if(!$result['rows']):?><div class="card empty-state"><h2>No candidates match these filters.</h2></div><?php else:?><?php foreach($result['rows'] as $c):?><a class="card candidate-card<?= !$c['active']?' inactive-candidate':'' ?>" href="<?= $e($url('admin/candidate?id='.$c['id'])) ?>"><?= Ui::candidateAvatar($c,'soft large-avatar') ?><div class="candidate-card-main"><div class="candidate-name-line"><h2><?= $e($c['full_name']) ?></h2><span class="badge <?= $c['active']?'green':'neutral' ?>"><?= $c['active']?'Active':'Inactive' ?></span><span class="resume-indicator <?= $c['resume_original_filename']?'has-resume':'' ?>"><?= $c['resume_original_filename']?'Resume ✓':'No resume' ?></span></div><p><?= $e($c['phone']) ?></p><?php if($c['tech_stack']):?><span class="skill-chips compact"><?php foreach(array_slice($c['tech_stack'],0,3) as $skill):?><span class="skill-chip<?= !$skill['active']?' inactive':'' ?>"><?= $e($skill['name']) ?></span><?php endforeach;?><?php if(count($c['tech_stack'])>3):?><span class="skill-more">+<?= count($c['tech_stack'])-3 ?> more</span><?php endif;?></span><?php else:?><span class="muted-text">Tech stack not added yet</span><?php endif;?><span class="badge <?= $c['classification']==='Genuine'?'green':'danger-badge' ?>"><?= $e($c['classification']) ?></span></div><div class="candidate-stat"><strong><?= $e($c['upcoming_count']) ?></strong><span>upcoming</span></div><?= Ui::icon('chevron') ?></a><?php endforeach;?><?php endif;?></section><?= Ui::pagination($result,$filters,'Candidate pages') ?>
